let rounds = 0;

// Function to move the plane
function movePlane() {
	let dot = document.getElementById('dot');
	let xmark = document.getElementById('xmark');
	let plane = document.getElementById('plane');
	let xmk = document.getElementById('xmk');

	// Set initial position
	let posX = 0;
	let posY = 0;
	dot.style.left = posX + 'px';
	dot.style.top = posY + 'px';

	// Move the plane
	let interval = setInterval(function() {
		posX += Math.floor(Math.random() * 10);
		posY += Math.floor(Math.random() * 10);
		dot.style.left = posX + 'px';
		dot.style.top = posY + 'px';

		// Check for click on the plane
		dot.onclick = function() {
			score++;
			rounds++;
			clearInterval(interval);
			movePlane();
		};

		// Check for missed click
		document.onclick = function(event) {
			if (event.target !== plane && event.target !== xmk) {
				xmark.style.left = (event.clientX - 10) + 'px';
				xmark.style.top = (event.clientY - 10) + 'px';
				xmark.style.display = 'block';
				setTimeout(function() {
					xmark.style.display = 'none';
				}, 1000);
			}
		};

		// End game after a certain number of rounds
		if (rounds === 10) {
			clearInterval(interval);
			alert('Game Over! Your score: ' + score);
		}
	}, 1000);
}

// Start the game
movePlane();
```

